    let row1 = item_row1(hero);
    // A controller-relative strand frame remains non-degenerate when pointing straight up/down.
    let gravity = hero.items.tracked_aim.map(|a|a.up.map(|v|-v)).unwrap_or_else(||to_f32x3(hero.gravity_dir));
    let gold = hero.weapons.gold[MORPH as usize] != 0;
    let tracked = hero.items.tracked_aim.is_some();
    let m = &mut hero.weapons.reactive.morph;
    let muzzle = m.muzzle;
    m.beam.lay(muzzle, row1);
    m.beam.gold = gold;
    if tracked {
