    /// Conservative spheres along the actual animated mesh, including cuffs and deployed parts.
    #[cfg(feature = "vr")]
    fn contact_shape(item: &Item, rows: [V4; 3], position: [f32; 3], scale: f32, palette: &[Rows]) -> Vec<(Vec3, f32)> {
        let triangles: Vec<[Vec3; 3]> = item.contact_triangles.iter().map(|t| t.map(|v| {
            let raw = Vec3::new(v.x as f32,v.y as f32,v.z as f32);
            if v.skin.count == 0 { return raw * (scale/1024.0); }
            (0..v.skin.count as usize).map(|k| {
                let posed = palette.get(v.skin.joints[k] as usize).map(|p| Mat4::from_cols_array_2d(p).transform_point3(raw)).unwrap_or(raw);
                posed * (v.skin.weights[k] as f32/256.0)
            }).sum::<Vec3>() * (scale/1024.0)
        })).collect();
        let points = triangles.iter().flatten();
        let (lo,hi) = points.fold((Vec3::splat(f32::INFINITY),Vec3::splat(f32::NEG_INFINITY)),|(lo,hi),&v|(lo.min(v),hi.max(v)));
        if !lo.is_finite() || !hi.is_finite() { return Vec::new(); }
        let extent = hi-lo;
        let axis = if extent.x >= extent.y && extent.x >= extent.z {0} else if extent.y >= extent.z {1} else {2};
        let count = ((extent[axis]/0.18).ceil() as usize).clamp(1,10);
        let step = extent[axis]/count as f32;
        let axes = Mat3::from_cols_array_2d(&rows.map(|r|[f32::from_bits(r[0]),f32::from_bits(r[1]),f32::from_bits(r[2])]));
        // Bound the largest singular value via the Gram matrix row sums. Unlike a
        // Frobenius bound this stays near one for the wrench's mild swing extension.
        let gram = axes.transpose()*axes;
        let stretch = (0..3).map(|i|gram.x_axis[i].abs()+gram.y_axis[i].abs()+gram.z_axis[i].abs()).fold(0.0_f32,f32::max).sqrt();
        (0..count).filter_map(|i| {
            let a = lo[axis]+step*i as f32;
            let b = a+step;
            let mut low = Vec3::splat(f32::INFINITY);
            let mut high = Vec3::splat(f32::NEG_INFINITY);
            for t in &triangles {
                let tl = t[0].min(t[1]).min(t[2]);
                let th = t[0].max(t[1]).max(t[2]);
                if tl[axis] > b || th[axis] < a {continue;}
                let mut l = tl; let mut h = th;
                l[axis] = l[axis].max(a); h[axis] = h[axis].min(b);
                low = low.min(l); high = high.max(h);
            }
            if !low.is_finite() {return None;}
            let centre = Vec3::from_array(position)+axes*((low+high)*0.5);
            Some((crate::tfrag_render::game_to_bevy(centre.to_array()),(high-low).length()*0.5*stretch+0.008))
        }).collect()
    }
