    /// Override only the presentation of the original hand item; retain its mesh, materials and animation.
    #[cfg(feature = "vr")]
    pub(crate) fn tracked_items(&mut self, hands: &[&rc_game::hero::items::HandItem]) {
        for item in &mut self.items {
            let hand = hands.iter().copied().find(|h| item.attach.slot == Slot::Hand && h.o_class == item.o_class);
            item.visible = hand.is_some();
            if let Some(h) = hand {
                item.position = h.position;
                item.scale = h.scale;
                item.rows = h.rows;
                item.state = h.anim;
                item.snapshot = h.snapshot.clone();
                if h.o_class == WRENCH_O_CLASS_I16 && h.mstate != 0 {
                    // A detached VR wrench is rigid; held-item spring modifiers must not
                    // deform the separate flying model after its presentation pose is set.
                    item.mods.clear();
                }
            }
        }
        self.ticks = self.ticks.wrapping_add(1);
    }
