    #[cfg(feature = "vr")]
    fn hand_palette(&self, play: &crate::gameplay::Play, ledge: bool) -> Option<Vec<Rows>> {
        let item = self.items.iter().find(|i| i.o_class == -30001)?;
        let a = &play.ratchet;
