    #[cfg(feature = "vr")]
    fn hand_frames(&self, play: &crate::gameplay::Play, ledge: bool) -> Option<[Rows; 2]> {
        let item = self.items.iter().find(|i| i.o_class == -30001)?;
        let a = &play.ratchet;
        let chains: [Vec<u8>;2] = [56,76].map(|mut j| {
            let mut c=vec![j as u8];
            while let Some(parent)=item.anim.parent(j) {j=parent;c.push(j as u8);}
            c.reverse();c
        });
        let layers=if ledge { Vec::new() } else { rc_game::hero::anim::pose_layers_with(&play.game.hero.weapons.layers,&a.layer_joints,&a.hold) };
        let mods=&play.game.mobys.mobys.get(play.game.hero_moby)?.joint_mods;
        moby_anim::evaluate_chains_posed(&item.anim,&a.state,a.snapshot.as_ref(),&chains.each_ref().map(|c|c.as_slice()),&layers,mods).try_into().ok()
    }
    #[cfg(feature = "vr")]
    fn weapon_attachment(&self, play: &crate::gameplay::Play) -> Option<Mat4> {
        let a = &play.ratchet;
        let item = self.items.iter().find(|i| i.o_class == -30001)?;
        let data = play.game.item_data.as_ref()?;
        let def = data.def(play.game.hero.items.slot.id);
        let chain = data.hero_chains.get(def.attach.max(0) as usize)?;
        let layers = rc_game::hero::anim::pose_layers_with(&play.game.hero.weapons.layers, &a.layer_joints, &a.hold);
        let mods = &play.game.mobys.mobys.get(play.game.hero_moby)?.joint_mods;
        let p = moby_anim::evaluate_chains_posed(&item.anim, &a.state, a.snapshot.as_ref(), &[chain], &layers, mods).into_iter().next()?;
        let mut rows = [0,1,2].map(|i|p[i].map(f32::to_bits));
        moby_anim::normalise_columns(&mut rows);
        let mut w = Mat4::from_cols_array_2d(&[rows[0].map(f32::from_bits),rows[1].map(f32::from_bits),rows[2].map(f32::from_bits),p[3]]);
        w.w_axis = (w.w_axis.truncate() * (item.scale / 1024.0)).extend(1.0);
        Some(w)
    }
