    #[cfg(feature="vr")]
    pub(crate) fn socket_item(&self, play:&crate::gameplay::Play, hand:&rc_game::hero::items::HandItem, target:usize, canonical:bool)->Option<rc_game::hero::items::HandItem> {
        let moby=play.game.mobys.mobys.get(target)?;
        let ratchet=self.items.iter().find(|i|i.o_class == -30001)?;
        let data=play.game.item_data.as_ref()?;
        let chain=data.hero_chains.get(data.def(play.game.hero.items.slot.id).attach.max(0) as usize)?;
        let mut state=play.ratchet.state;
        if canonical {
            let seq=if moby.o_class==615 {0x57} else if play.game.hero.gadgets.hydro_full {0x84} else {0x47};
            let frame=(0..=255u8).rev().find(|&f|ratchet.anim.frame(seq,f).is_some()).unwrap_or(0);
            state.seq_a=seq;state.seq_b=seq;state.frame_a=frame;state.frame_b=frame;state.t=0.0;
        }
        let snapshot = if canonical { None } else { play.ratchet.snapshot.as_ref() };
        let p=moby_anim::evaluate_chains_posed(&ratchet.anim,&state,snapshot,&[chain],&[],&[]).into_iter().next()?;
        let mut rows=[0,1,2].map(|i|p[i].map(f32::to_bits));
        moby_anim::normalise_columns(&mut rows);
        let attachment=Mat3::from_cols_array_2d(&rows.map(|r|[f32::from_bits(r[0]),f32::from_bits(r[1]),f32::from_bits(r[2])]));
        let yaw=moby.rotation[2]+if moby.o_class==615 {std::f32::consts::PI} else {0.0};
        let body=Mat3::from_rotation_z(yaw);
        let mut origin=Vec3::new(moby.position[0],moby.position[1],moby.position[2]);
        if moby.o_class==615 {
            if let Some(chain)=play.svc.joint_lists.get(&615).and_then(|v|v.first()) {
                use rc_game::moby_update::services::ClassData;
                if let Some(class)=play.classes.anim(615) {
                    let p=moby_anim::evaluate_chains(class,&moby.anim,None,&[chain]).into_iter().next()?[3];
                    let axes=Mat3::from_cols_array_2d(&[0,1,2].map(|i|moby.rows[i][..3].try_into().unwrap()));
                    origin+=axes*Vec3::new(p[0],p[1],p[2])*(moby.scale/1024.0);
                }
            }
        }
        let axes=body*attachment;
        let mut item=hand.clone();
        item.position=(origin+body*Vec3::new(p[3][0],p[3][1],p[3][2])*(self.host_scale/1024.0)).to_array();
        item.rows=[0,1,2].map(|i|{let v=axes.col(i);[v.x.to_bits(),v.y.to_bits(),v.z.to_bits(),0]});
        Some(item)
    }
