/// The main-world entities that are effects (this frame).
#[derive(Resource, Default)]
struct EffectEntities(HashSet<MainEntity>);

/// Cached by pipeline, not by the lifetime of the main-world entity. A retained transparent phase
/// can still contain an old level's draw after its DisplayEffect marker has been despawned.
#[derive(Resource, Default)]
struct EffectFormats(HashMap<CachedRenderPipelineId, bool>);

fn is_effect(item: &Transparent3d, set: &EffectEntities, cache: &PipelineCache, formats: &mut EffectFormats) -> bool {
    if let Some(&effect) = formats.0.get(&item.pipeline) { return effect; }
    // Descriptors of newly queued pipelines are not accessible yet. Such a pipeline cannot draw;
    // keep the marker fallback without caching it until the compiled descriptor is available.
    if cache.get_render_pipeline(item.pipeline).is_none() { return set.0.contains(&item.entity.1); }
    let effect = cache.get_render_pipeline_descriptor(item.pipeline).fragment.as_ref()
        .is_some_and(|f| f.targets.iter().flatten().any(|t| t.format == EFFECT_FORMAT));
    formats.0.insert(item.pipeline, effect);
    effect
}

